<template>
  <section id="conditional-actions" class="chart-plan-results chart-results-simple" aria-label="Chart result and conditional reference plans">
    <div class="chart-result-topline"><p>Chart analysis · {{ run.observation?.chart_timeframes?.join(' + ')||'Saved screenshot' }}</p><span>{{ decisionWord==='WAIT'?'Waiting for confirmation':decisionWord+' condition recorded' }}</span></div>
    <div class="chart-result-summary"><div><p class="result-eyebrow">Current decision</p><strong class="decision-word">{{ decisionWord }}</strong><h2>{{ isNoTrade(run)?'Wait for the chart to confirm a setup.':'Follow the recorded setup conditions.' }}</h2><p>{{ biasLabel }} · Chart reference {{ plottedReference }}</p></div><button class="chart-agents-link" @click="$emit('discussion')">See agent discussion<ResearchIcon name="arrow"/></button></div>
    <div v-if="options.length" class="scenario-heading"><h2>Conditional scenarios</h2><p>Select a scenario to see its levels and the sequence that must happen first.</p></div>
    <nav class="scenario-picker" aria-label="Recorded chart scenarios"><button v-for="option in options" :key="option.key" :aria-pressed="selectedOption?.key===option.key" :class="{selected:selectedOption?.key===option.key}" @click="planKey=option.key"><span>{{ option.side==='long'?'Long':option.side==='short'?'Short':'Watch' }}</span><strong>{{ option.label }}</strong><small :class="{'blocked-label':option.kind==='rejected'}">{{ option.kind==='reference'?'Levels ready · wait for trigger':option.kind==='rejected'?'Review · below 1.25R':'Needs more chart structure' }}</small><small v-if="option.plan" class="scenario-price-preview">Entry {{ price(option.plan.entry,option.plan.level_bases?.entry) }} · TP1 {{ price(option.plan.targets?.[0],option.plan.level_bases?.targets?.[0]) }}</small></button></nav>
    <p v-if="!options.length" class="freshness-inline">No supported scenario is recorded yet. Saved chart evidence remains available below.</p>
    <div class="chart-result-primary"><div class="result-chart"><slot name="chart"/></div><section class="selected-scenario" aria-label="Selected chart scenario"><header><p>Selected scenario</p><h2>{{ selectedOption?.label||'No complete setup' }}</h2><span v-if="selectedOption">{{ selectedOption.side==='long'?'Conditional long':selectedOption.side==='short'?'Conditional short':'Watch' }}</span></header>
      <p v-if="selectedOption" class="scenario-intent">{{ scenarioDescription(selectedOption.scenario||selectedPlan) }}</p>
      <template v-if="selectedPlan"><dl class="selected-prices"><div class="entry-price"><dt>Entry · after confirmation</dt><dd>{{ entryPrice(selectedPlan) }}</dd></div><div class="stop-price"><dt>Stop loss · SL</dt><dd>{{ price(selectedPlan.stop,selectedPlan.level_bases?.stop) }}</dd></div><div v-for="(target,index) in selectedPlan.targets||[]" :key="index" class="target-price"><dt>{{ index===0&&selectedPlan.target_policy?.fallback_applied?'TP1 · calculated at 1.25R':'Take profit · TP'+(index+1) }}</dt><dd>{{ price(target,selectedPlan.level_bases?.targets?.[index]) }}</dd></div></dl><div class="scenario-policy" :class="{blocked:!referencePayoff(selectedPlan).eligible}"><strong>{{ referencePayoff(selectedPlan).eligible?(selectedPlan.target_policy?.fallback_applied?'Calculated 1.25R target · wait for confirmation':'Conditional plan · wait for confirmation'):'Review target and costs' }}</strong><p>{{ payoffRLabel(referencePayoff(selectedPlan)) }} to TP1 at the worst allowed fill · requires ≥1.25R before costs.</p><p v-if="!referencePayoff(selectedPlan).eligible">These are the recorded reference levels. A trigger alone does not make this setup eligible.</p></div></template>
      <template v-else><p class="missing-prices">{{ selectedOption?.kind==='rejected'?'This reference does not qualify under the position policy.':selectedOption?incompleteScenarioDisplay(run,selectedOption.scenario).label:'Entry, stop loss and targets are unavailable.' }}</p><p class="missing-reason">{{ selectedOption?.rejected?referencePayoff(selectedOption.rejected).reason:selectedOption?.scenario?.missing_structure?.[0]||run.verdict.no_plan_reason }}</p><div v-if="selectedOption?.scenario" class="observed-references"><small>Observed references · not position levels</small><span v-for="level in incompleteScenarioDisplay(run,selectedOption.scenario).references" :key="level.id">{{ level.kind.replaceAll('_',' ') }} {{ price(level.price,level.basis) }}</span></div><button v-if="selectedOption?.kind==='rejected'" class="saved-levels-button" @click="showRejected">Inspect original rejected references</button></template>
      <div v-if="selectedPlan?.target_policy?.fallback_applied" class="calculated-target-note"><strong>How TP1 was set</strong><p>The chart target was {{ price(selectedPlan.target_policy.source_tp1) }} ({{ selectedPlan.target_policy.source_tp1_r.toFixed(3) }}R). Entry and SL stay fixed; the displayed TP1 is calculated at 1.25 times the risk.</p><p>This target is calculated, not a support or resistance level observed on the chart.</p></div>
      <p v-if="selectedPlan?.target_policy?.obstacles_before_target?.length" class="target-obstacles"><strong>Chart levels before TP1:</strong> {{ selectedPlan.target_policy.obstacles_before_target.map(level=>price(level.price,level.basis)).join(' · ') }}. Price must clear these for the target to be reached.</p>
    </section></div>
    <section v-if="sequence.length||cancellation" class="scenario-execution" aria-label="Scenario trigger and confirmation">
      <div v-if="sequence.length" class="selected-trigger"><h3>Before any entry</h3><ol class="scenario-steps"><li v-for="(step,index) in sequence" :key="index"><span class="step-number">{{ index+1 }}</span><div><strong>{{ step.label }}</strong><p>{{ step.condition }}</p></div></li></ol></div>
      <div v-if="cancellation" class="scenario-cancel"><h3>Cancel / skip if</h3><p>{{ cancellation }}</p></div>
    </section>
    <div v-if="selectedOption" class="chart-reasoning-layout"><section><h2>Reasoning</h2><h3>{{ selectedOption.label }}</h3><p>{{ selectedOption.scenario?.summary||selectedPlan?.trigger||scenarioDescription(selectedOption.scenario||selectedPlan) }}</p></section><section><h2>When to reassess</h2><p>{{ selectedOption.scenario?.invalidation?.condition||selectedPlan?.invalidation||'No invalidation condition was recorded.' }}</p><p v-if="selectedOption.scenario?.no_trade_reason" class="reasoning-note">{{ selectedOption.scenario.no_trade_reason }}</p></section></div>
    <details v-if="selectedPlan" class="selected-conditions"><summary>Full ordered conditions & price basis</summary><ChartPlanReference ref="selectedCard" :run="run" :plan="selectedPlan" selected @select="planKey=exitPlanKey(run,selectedPlan)" @exits="$emit('exits',$event)"/></details>
    <p class="freshness-inline">Saved screenshot references · confirmation is not monitored live · TP1 must reach at least 1.25R at the worst allowed fill.<span v-if="freshness.quote_discrepancies?.length"> Source / quote mismatch — see evidence below.</span></p>
    <details v-if="rejected.length" ref="rejectedDisclosure" class="details-evidence"><summary>Below-threshold / rejected references · {{ rejected.length }}</summary><article v-for="plan in rejected" :key="plan.plan_id||plan.scenario_id" class="watch-card"><h3>{{ strategyLabel(plan.strategy) }} · {{ plan.side }}</h3><p>{{ scenarioDescription(plan) }}</p><p>{{ referencePayoff(plan).reason }} Original entry {{ price(plan.entry,plan.level_bases?.entry||(plan.approximate?'axis_estimate':null)) }} · SL {{ price(plan.stop,plan.level_bases?.stop||(plan.approximate?'axis_estimate':null)) }} · targets {{ plan.targets?.map((value,index)=>price(value,plan.level_bases?.targets?.[index]||(plan.approximate?'axis_estimate':null))).join(' / ') }} · conservative {{ referencePayoff(plan).r?.toFixed(4)||'unavailable' }}R.</p><p>{{ plan.trigger }}</p><p>Cancel if: {{ plan.invalidation }}</p><details><summary>Original ordered conditions & price basis</summary><p>{{ originalScenario(plan)?.summary }}</p><ol><li v-for="(step,index) in originalScenario(plan)?.steps||[]" :key="index">{{ step.condition }}</li></ol><p>Entry basis: {{ plan.entry_zone?.evidence||plan.level_reasons?.entry||'Not recorded' }}</p><p>Stop basis: {{ plan.level_reasons?.stop||'Not recorded' }}</p><p v-for="(reason,index) in plan.level_reasons?.targets||[]" :key="index">TP{{ index+1 }}: {{ reason }}</p></details></article></details>
    <details ref="detailsEvidence" class="details-evidence"><summary>Details & evidence</summary>
    <details class="result-disclosure current-blockers"><summary>Why wait</summary><p>{{ run.verdict.trade_readiness?.summary }}</p><ul><li v-for="(condition,index) in run.verdict.trade_readiness?.conditions||[]" :key="index"><strong>{{ condition.applies_to }} · {{ condition.category.replaceAll('_',' ') }}</strong><p>{{ condition.explanation }}</p><p>{{ condition.reassess_when?.join(' Then: ') }}</p></li></ul></details>
    <details class="result-disclosure result-freshness"><summary>Source & price provenance</summary>
      <p>{{ run.verdict.bias_reason||run.verdict.headline }}</p><p><strong>Chart market time:</strong> {{ freshness.chart_market_times?.length?freshness.chart_market_times.map(time=>time.text+' (printed, unverified)').join(' · '):'Unknown / unverified' }}</p><p>Source uploaded {{ date(freshness.source_uploaded_at) }} · Actual capture time {{ freshness.capture_time||'unknown' }} · Assessment created {{ date(freshness.assessment_created_at||run.created_at) }}</p>
      <p v-for="(mismatch,index) in freshness.quote_discrepancies||[]" :key="index" class="freshness-warning">Plotted reference {{ price(mismatch.plotted_reference) }} differs from displayed quote {{ price(mismatch.displayed_quote) }}. The quote does not replace the historical chart levels.</p><p>{{ freshness.summary||'These are screenshot references; chart market time is unverified.' }}</p>
      <details v-if="freshness.reported_limitations?.length||freshness.reported_observation_summary"><summary>Original observations and limitations</summary><p>{{ freshness.reported_observation_summary }}</p><ul><li v-for="limitation in freshness.reported_limitations||[]" :key="limitation">{{ limitation }}</li></ul></details>
      <div class="levels-scroll"><table><thead><tr><th>Observed structure</th><th>Reference price</th><th>Why it matters</th></tr></thead><tbody><tr v-for="level in structuralLevels" :key="level.id"><td>{{ level.kind.replaceAll('_',' ') }}</td><td>{{ price(level.price,level.basis) }}</td><td>{{ level.evidence }}</td></tr></tbody></table></div>
      <p class="result-note">Complete references with coherent source/payoff are ordered first. The moderator’s evidence order is retained within each group; R is not a measured trading edge.</p><p v-if="run.verdict.execution_plan_synthesis" class="result-note">Focused execution planning {{ run.verdict.execution_plan_synthesis.status==='validated'?'validated these source-bounded prices':'could not validate additional prices' }}. Saved agents did not run another debate.</p><p v-if="run.reassessed_from_run_id" class="result-note">This assessment reused saved evidence and discussions; market time was not refreshed.</p>
    </details>
    <details class="result-disclosure result-coverage"><summary>Approaches assessed</summary><p v-for="assessment in run.verdict.strategy_assessments||[]" :key="assessment.strategy"><strong>{{ strategyLabel(assessment.strategy) }} · {{ assessment.outcome.replaceAll('_',' ') }}:</strong> {{ assessment.reason }}</p></details>
    <slot name="evidence"/><slot name="calculator"/></details>
  </section>
</template>
<script setup>
import {computed,nextTick,ref,watch} from 'vue'
import ChartPlanReference from './ChartPlanReference.vue'
import ResearchIcon from './ResearchIcon.vue'
import {chartScenarioOptions,selectChartScenario} from '../utils/chartWorkspace.mjs'
import {isNoTrade,strategyLabel,rankedReferencePlans,rejectedTradePlans} from '../utils/tradeDecision.mjs'
import {referencePayoff,payoffRLabel} from '../utils/payoffPolicy.mjs'
import {scenarioDescription,scenarioTrigger,resultScenarioGroups,incompleteScenarioDisplay,scenarioSequence,scenarioCancellation} from '../utils/scenarioPresentation.mjs'
import {exitPlanKey} from '../utils/tradeExitPlan.mjs'
const props=defineProps({run:Object})
const planKey=defineModel('planKey',{default:''})
defineEmits(['exits','discussion'])
const selectedCard=ref(null),detailsEvidence=ref(null),rejectedDisclosure=ref(null)
const ranking=computed(()=>rankedReferencePlans(props.run))
const plans=computed(()=>ranking.value.plans)
const options=computed(()=>chartScenarioOptions(props.run))
watch(()=>options.value.map(o=>o.key).join('|'),()=>{planKey.value=selectChartScenario(options.value,planKey.value)},{immediate:true,flush:'sync'})
const selectedOption=computed(()=>options.value.find(o=>o.key===planKey.value)||options.value[0])
const decisionWord=computed(()=>{const permitted=plans.value.filter(plan=>plan.entry_permission===true);return !isNoTrade(props.run)&&permitted.length===1?permitted[0].side.toUpperCase():'WAIT'})
const selectedPlan=computed(()=>selectedOption.value?.plan||null)
const sequence=computed(()=>scenarioSequence(selectedOption.value?.scenario,selectedPlan.value))
const cancellation=computed(()=>scenarioCancellation(selectedOption.value?.scenario,selectedPlan.value))
const alternatives=computed(()=>plans.value.filter(plan=>plan!==selectedPlan.value))
const freshness=computed(()=>props.run.verdict?.freshness||{})
const structuralLevels=computed(()=>(props.run.observation?.levels||[]).filter(level=>['support','resistance','swing_high','swing_low'].includes(level.kind)))
const rejected=computed(()=>rejectedTradePlans(props.run))
const watchlists=computed(()=>resultScenarioGroups(props.run).watchlists)
const plottedReference=computed(()=>{const level=props.run.observation?.levels?.find(l=>['plotted_price','current_price'].includes(l.kind));return level?price(level.price,level.basis):'Not recorded'})
const biasLabel=computed(()=>({bullish:'Bullish lean',bearish:'Bearish lean',mixed:'Mixed / range',no_setup:'Directional evidence insufficient'}[props.run.verdict.bias]||props.run.verdict.headline))
const originalScenario=plan=>props.run.verdict?.strategy_scenarios?.find(scenario=>scenario.id===plan.scenario_id&&scenario.plan_id===plan.plan_id)
const entryPrice=plan=>plan.entry_zone?`${price(plan.entry_zone.lower,plan.entry_zone.precision)} – ${price(plan.entry_zone.upper,plan.entry_zone.precision)}`:price(plan.entry,plan.level_bases?.entry)
const date=value=>value?new Date(value).toLocaleString('en-AU'):'unknown'
const price=(value,basis)=>typeof value==='number'&&Number.isFinite(value)&&value>0?(basis==='axis_estimate'?'≈ ':'')+value.toLocaleString('en-US',{maximumFractionDigits:8}):'Missing'
async function showConditions(key){if(options.value.some(o=>o.key===key))planKey.value=key;await nextTick();const disclosure=selectedCard.value?.$el?.closest('details');if(disclosure)disclosure.open=true;selectedCard.value?.showConditions();await nextTick();selectedCard.value?.$el?.scrollIntoView({block:'start'})}
async function showRejected(){if(rejectedDisclosure.value)rejectedDisclosure.value.open=true;await nextTick();rejectedDisclosure.value?.scrollIntoView({block:'start'})}
function openEvidence(){if(detailsEvidence.value)detailsEvidence.value.open=true}
defineExpose({showConditions,openEvidence})
</script>
